-- Schema for the Task Assignment app. See docs/design.md → Schema.
-- Run by postgres' initdb.d on first start, and by the API tests against a fresh schema.
-- The database guards integrity only; the backend owns every business rule.
-- Every id is a UUIDv7 generated by the backend (the `uuid` package); there is no DB default.

CREATE TABLE skill (
  id   uuid PRIMARY KEY,
  name text NOT NULL UNIQUE
);

CREATE TABLE developer (
  id   uuid PRIMARY KEY,
  name text NOT NULL
);

CREATE TABLE developer_skill (
  developer_id uuid NOT NULL REFERENCES developer(id),
  skill_id     uuid NOT NULL REFERENCES skill(id),
  PRIMARY KEY (developer_id, skill_id)
);

CREATE TABLE task (
  id           uuid     PRIMARY KEY,
  title        text     NOT NULL,
  status       text     NOT NULL DEFAULT 'TODO',      -- allowed values checked in the backend
  -- USER: a person picked the skills (create or edit). LLM: identified, at least one skill.
  -- FAILED: no skills; waits for a person. Values checked in the backend.
  skill_source text     NOT NULL,
  parent_id    uuid     REFERENCES task(id),           -- NULL for a top-level task
  root_id      uuid     NOT NULL REFERENCES task(id),  -- top-level task of the tree; itself for a root
  position     smallint NOT NULL,                      -- order among siblings, from the form; 0 for a root
  assignee_id  uuid     REFERENCES developer(id)
);
CREATE INDEX task_parent_idx   ON task(parent_id);
CREATE INDEX task_root_idx     ON task(root_id);
CREATE INDEX task_assignee_idx ON task(assignee_id);

CREATE TABLE task_skill (
  task_id  uuid NOT NULL REFERENCES task(id),
  skill_id uuid NOT NULL REFERENCES skill(id),
  PRIMARY KEY (task_id, skill_id)
);
